def merge_intervals(xs: list[tuple[int, int]]) -> list[tuple[int, int]]:
    if not xs:
        return []
    xs_sorted = sorted(xs)
    merged = [xs_sorted[0]]
    for s, e in xs_sorted[1:]:
        last_s, last_e = merged[-1]
        if s <= last_e:
            merged[-1] = (last_s, last_e if last_e > e else e)
        else:
            merged.append((s, e))
    return merged
```

